<script src="https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/gsap.min.js"></script>
<script>
(function(){
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  function initLoop(){
    var strip = document.getElementById('strip-adv-loop');
    if(!strip) return;
    // seamless infinite loop — no stops — linear
    var totalWidth = strip.scrollWidth / 2; // one set
    gsap.set(strip,{x:0});
    gsap.to(strip,{
      x: -totalWidth,
      duration: 28,
      ease: "none",
      repeat: -1,
      modifiers: {
        x: gsap.utils.unitize(function(x){ return parseFloat(x) % totalWidth; })
      }
    });
    // pause on hover for UX, resume on leave — still no stops when not hovering
    strip.addEventListener('mouseenter', function(){ gsap.to(strip,{timeScale:0.25, duration:0.4}); });
    strip.addEventListener('mouseleave', function(){ gsap.to(strip,{timeScale:1, duration:0.4}); });
  }
  if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', initLoop); } else { setTimeout(initLoop, 100); }
})();
</script>
